import{_ as t,o as a,c as o,a2 as s}from"./chunks/framework.G0y0PQA7.js";const i="/relio/shots/en/ermaster-open-demo.png",r="/relio/shots/en/ermaster-target-version.png",p=JSON.parse('{"title":"Coming from ERMaster","description":"","frontmatter":{},"headers":[],"relativePath":"en/quick/from-ermaster.md","filePath":"en/quick/from-ermaster.md"}'),n={name:"en/quick/from-ermaster.md"};function l(h,e,d,m,c,f){return a(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="coming-from-ermaster" tabindex="-1">Coming from ERMaster <a class="header-anchor" href="#coming-from-ermaster" aria-label="Permalink to &quot;Coming from ERMaster&quot;">​</a></h1><p>Relio uses the same <code>.erm</code> files as ERMaster. There is nothing to convert: open your files, and anything you save still opens in ERMaster. You can keep working together even if some of your team still use ERMaster.</p><ol><li><p><strong>Open</strong> — Choose File › Open… (<kbd>Ctrl</kbd>+<kbd>O</kbd>) or drag an <code>.erm</code> file onto the window. Several files open as tabs.</p><figure class="shot" data-scene="ermaster-open-demo"><img src="'+i+'" alt="An .erm file made with ERMaster, opened in Relio" loading="lazy"><figcaption>An .erm file made with ERMaster, opened in Relio</figcaption></figure></li><li><p><strong>Pick the target database version</strong> — Click the left end of the status bar (for example &quot;PostgreSQL 16&quot;) and choose the database version you actually use. Design checks and DDL follow that version&#39;s syntax. If you are not sure, leave it as it is.</p><figure class="shot" data-scene="ermaster-target-version"><img src="'+r+'" alt="Choosing the target database version from the status bar" loading="lazy"><figcaption>Choosing the target database version from the status bar</figcaption></figure></li><li><p><strong>Save</strong> — <kbd>Ctrl</kbd>+<kbd>S</kbd>. Relio writes a temporary file completely and then swaps it in, so the original file is not damaged even if the app stops while saving.</p></li></ol><h2 id="why-mixing-tools-is-safe" tabindex="-1">Why mixing tools is safe <a class="header-anchor" href="#why-mixing-tools-is-safe" aria-label="Permalink to &quot;Why mixing tools is safe&quot;">​</a></h2><ul><li>Relio always draws tables at the size that fits their content, but leaves the sizes and positions written in the file alone. Simply opening and saving a file does not change it.</li><li>Settings that only Relio has, such as the target database version and design check ignores, are remembered per file on this PC — not in the <code>.erm</code>.</li><li>When you view several categories together, that state is not written to the file; only the last category you chose is kept.</li></ul><h2 id="what-is-different" tabindex="-1">What is different <a class="header-anchor" href="#what-is-different" aria-label="Permalink to &quot;What is different&quot;">​</a></h2><ul><li>Relio runs on its own, without Eclipse.</li><li>Excel output is <code>.xlsx</code>. ERMaster <code>.xls</code> templates still work.</li><li>Database passwords are stored in the Windows Credential Manager by default, not in the <code>.erm</code>.</li><li>Columns that use a type only Relio has (such as <code>json</code>) show an empty type in ERMaster. <a href="/relio/en/features/troubleshooting#types-look-empty-in-ermaster">More</a></li><li>Known problems are fixed, such as DDL syntax that failed on some databases and quotes or empty values in test data SQL.</li><li>New: design checks, suggestions while typing, Hangul initial-consonant search for Korean names, and model-level merging.</li></ul><div class="warning custom-block"><p class="custom-block-title">Warning</p><p>If your team mixes ERMaster and Relio and uses Git, set up line endings first. Otherwise every save can make the whole file look changed. See <a href="/relio/en/quick/git#preparing-the-repository">Working together with Git</a>.</p></div><p><strong>More</strong> → <a href="/relio/en/features/file">File</a> · <a href="/relio/en/features/ddl">DDL</a> · <a href="/relio/en/features/import">Import and other formats</a> · <a href="/relio/en/features/troubleshooting#types-look-empty-in-ermaster">Types look empty in ERMaster</a></p>',9)])])}const u=t(n,[["render",l]]);export{p as __pageData,u as default};
